ALTER POLICY notification_own ON public.user_notifications USING(user_id=auth.uid() AND public.task_staff_active(auth.uid()) AND (task_id IS NULL OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.id=task_id AND public.task_can_read(t))));
CREATE OR REPLACE FUNCTION public.task_installment_balance(_id uuid) RETURNS numeric LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT x.amount_incl_vat-coalesce((SELECT sum(a.amount_incl_vat) FROM public.receipt_allocations a JOIN public.receipts r ON r.id=a.receipt_id WHERE a.installment_id=x.id AND r.status='verified' AND r.reverses_id IS NULL AND r.archived_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.receipts rev WHERE rev.reverses_id=r.id)),0) FROM public.installments x WHERE x.id=_id $$;
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.assign_task(uuid,uuid,text)'::regprocedure) INTO d;d:=replace(d,'UPDATE public.tasks SET assignee_user_id=_user','IF public.has_role(_user,''sales_agent'') AND ((t.entity_type=''opportunity'' AND NOT EXISTS(SELECT 1 FROM public.opportunities WHERE id=t.entity_id AND owner_user_id=_user)) OR (t.entity_type=''party'' AND NOT EXISTS(SELECT 1 FROM public.opportunities WHERE party_id=t.entity_id AND owner_user_id=_user AND outcome IS NULL)) OR (t.entity_type=''booking'' AND NOT EXISTS(SELECT 1 FROM public.opportunities WHERE booking_id=t.entity_id AND owner_user_id=_user))) THEN RAISE EXCEPTION ''المهمة تخص عميل وسيط آخر'';END IF;UPDATE public.tasks SET assignee_user_id=_user');EXECUTE d;SELECT pg_get_functiondef('public.task_source_trigger()'::regprocedure) INTO d;d:=replace(d,'SET assignee_user_id=NEW.owner_user_id','SET assignee_user_id=CASE WHEN public.task_staff_active(NEW.owner_user_id) THEN NEW.owner_user_id ELSE public.task_pick_role(''leasing_manager'') END');EXECUTE d;END $$;
CREATE OR REPLACE FUNCTION public.resolve_task_source() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.tasks;ids uuid[];BEGIN IF TG_TABLE_NAME='bookings' THEN IF NEW.status<>'pending' OR NEW.archived_at IS NOT NULL THEN FOR t IN SELECT * FROM public.tasks WHERE entity_type='booking' AND entity_id=NEW.id AND status='open' AND source_key IS NOT NULL LOOP UPDATE public.tasks SET status='cancelled',completed_at=now(),outcome_note='الحجز لم يعد طلبًا مفتوحًا',updated_at=now() WHERE id=t.id;END LOOP;END IF;ELSIF TG_TABLE_NAME='contracts' THEN IF NEW.status<>'active' THEN UPDATE public.tasks SET status='cancelled',completed_at=now(),outcome_note='العقد غير فعال',updated_at=now() WHERE entity_type='contract' AND entity_id=NEW.id AND status='open' AND source_key IS NOT NULL;END IF;ELSIF TG_TABLE_NAME='installments' THEN IF NEW.status IN('paid','waived') THEN UPDATE public.tasks SET status='done',completed_at=now(),outcome_note='القسط مسدد أو معفى من المصدر المعتمد',updated_at=now() WHERE entity_type='installment' AND entity_id=NEW.id AND type='installment_due' AND status='open';END IF;END IF;RETURN NEW;END $$;
CREATE OR REPLACE TRIGGER booking_task_resolution AFTER UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.resolve_task_source();CREATE OR REPLACE TRIGGER contract_task_resolution AFTER UPDATE ON public.contracts FOR EACH ROW EXECUTE FUNCTION public.resolve_task_source();CREATE OR REPLACE TRIGGER installment_task_resolution AFTER UPDATE ON public.installments FOR EACH ROW EXECUTE FUNCTION public.resolve_task_source();REVOKE ALL ON FUNCTION public.resolve_task_source() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.task_summary_schedule_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE utc_time time;cron_text text;BEGIN IF OLD.task_summary_time IS DISTINCT FROM NEW.task_summary_time THEN utc_time:=(NEW.task_summary_time-interval '3 hours')::time;cron_text:=extract(minute FROM utc_time)::integer||' '||extract(hour FROM utc_time)::integer||' * * *';PERFORM cron.alter_job((SELECT jobid FROM cron.job WHERE jobname='mnicity-task-daily-summary'),schedule:=cron_text);END IF;RETURN NEW;END $$;CREATE OR REPLACE TRIGGER task_summary_schedule AFTER UPDATE ON public.app_settings FOR EACH ROW EXECUTE FUNCTION public.task_summary_schedule_sync();REVOKE ALL ON FUNCTION public.task_summary_schedule_sync() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.tasks_regression_tests() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k uuid;u uuid;tests integer:=0;oldcount integer;BEGIN IF NOT public.has_permission('tasks.manage','edit') THEN RAISE EXCEPTION 'الاختبار للأدمن';END IF;IF timestamp '2026-11-06 00:05'+make_interval(hours=>24)<>timestamp '2026-11-07 00:05' THEN RAISE EXCEPTION 'response deadline';END IF;tests:=tests+1;IF date '2026-11-10'-3<>date '2026-11-07' THEN RAISE EXCEPTION 'installment deadline';END IF;tests:=tests+1;IF (date '2026-03-31'-interval '1 month')::date<>date '2026-02-28' THEN RAISE EXCEPTION 'calendar month';END IF;tests:=tests+1;IF date '2026-12-01'-7<>date '2026-11-24' THEN RAISE EXCEPTION 'week deadline';END IF;tests:=tests+1;IF timestamp '2026-11-07 00:00' AT TIME ZONE 'Asia/Riyadh'<>timestamptz '2026-11-06 21:00+00' THEN RAISE EXCEPTION 'timezone';END IF;tests:=tests+1;SELECT id INTO u FROM public.units ORDER BY id LIMIT 1;IF u IS NULL THEN RAISE EXCEPTION 'test unit unavailable';END IF;BEGIN SELECT count(*) INTO oldcount FROM public.tasks;k:=public.create_task('اختبار معزول للمهام','manual',auth.uid(),now(),'unit',u,'اختبار معاملات المهام المعزول');IF NOT EXISTS(SELECT 1 FROM public.user_notifications WHERE task_id=k AND user_id=auth.uid()) THEN RAISE EXCEPTION 'notification missing';END IF;tests:=tests+1;PERFORM public.set_task_state(k,'done','نتيجة اختبار المهمة المعزول');IF NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=k AND status='done' AND completed_at IS NOT NULL) THEN RAISE EXCEPTION 'completion failed';END IF;tests:=tests+1;IF NOT EXISTS(SELECT 1 FROM public.audit_log WHERE entity_table='tasks' AND entity_id=k::text) THEN RAISE EXCEPTION 'audit missing';END IF;tests:=tests+1;RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='rollback task test';EXCEPTION WHEN no_data_found THEN NULL;END;IF (SELECT count(*) FROM public.tasks)<>oldcount THEN RAISE EXCEPTION 'test did not rollback';END IF;RETURN jsonb_build_object('passed',true,'assertions',8,'rolled_back',true);END $$;
REVOKE ALL ON FUNCTION public.tasks_regression_tests() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.tasks_regression_tests() TO authenticated;
SELECT to_regprocedure('public.tasks_regression_tests()') IS NOT NULL AS tests_ready;